         "A) రూ.10,000 కోట్లు",
         "B) రూ.21,083 కోట్లు",
         "C) రూ.30,000 కోట్లు",
         "D) రూ.50,000 కోట్లు",
         "B",
         "2025-26లో భారత రక్షణ ఎగుమతులు రూ.21,083 కోట్లు నమోదు చేశాయి. India's defence exports reached Rs 21,083 crore in 2025-26.",
