         "B",
         "అగ్నివీర్ పథకం కింద సైనికుల సేవా కాలం 4 సంవత్సరాలు, తర్వాత 25% ను శాశ్వత సేవలో ఉంచుతారు. Agniveers serve for 4 years under the Agnipath scheme, after which 25% are retained in permanent service.",
